	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(10L, TimeUnit.SECONDS)) {
				throw new AssertionError("timed out awaiting submission-drain test coordination");
			}
		} catch (InterruptedException problem) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted awaiting submission-drain test coordination", problem);
		}
	}

	private static final class HandshakedExecutor extends ThreadPoolExecutor {
		private final CountDownLatch taskStarted;
		private final CountDownLatch releaseTask;
		private final CountDownLatch taskFinished;
		private final CountDownLatch rejectionObserved;
		private final CountDownLatch releaseRejection;
		private final AtomicBoolean taskActive;
		private final AtomicBoolean firstSubmission = new AtomicBoolean(true);

		private HandshakedExecutor(CountDownLatch taskStarted, CountDownLatch releaseTask,
				CountDownLatch taskFinished, CountDownLatch rejectionObserved, CountDownLatch releaseRejection,
				AtomicBoolean taskActive) {
			super(1, 1, 0L, TimeUnit.MILLISECONDS, new SynchronousQueue<>());
			this.taskStarted = taskStarted;
			this.releaseTask = releaseTask;
			this.taskFinished = taskFinished;
			this.rejectionObserved = rejectionObserved;
			this.releaseRejection = releaseRejection;
			this.taskActive = taskActive;
		}

		@Override
		protected <T> RunnableFuture<T> newTaskFor(Callable<T> callable) {
			return super.newTaskFor(() -> {
				taskActive.set(true);
				taskStarted.countDown();
				try {
					await(releaseTask);
					return callable.call();
				} finally {
					// This must precede Future completion: an executor wrapper's finally can run after get() returns.
					taskActive.set(false);
					taskFinished.countDown();
				}
			});
		}

		@Override
		public void execute(Runnable command) {
			if (firstSubmission.compareAndSet(true, false)) {
				super.execute(command);
				await(taskStarted);
				return;
			}
			try {
				super.execute(command);
			} catch (RuntimeException | Error problem) {
				rejectionObserved.countDown();
				await(releaseRejection);
				throw problem;
			}
		}
	}

